if(!vf3_away_batch206_adapter_contains(entry)) { s->failed_pc=entry; return 0; }
uint32_t pc=entry&0x1fffffffu;
if(pc<=0x0c0aa73eu) return vf3_away_batch206_adapter_0(entry,s,ram);
